package com.tecsup.medico.model; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity @Table(name="medico")public class Medico{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="id_medico")private Long id;@NotBlank @Column(unique=true,length=20)private String cmp;@NotBlank @Column(nullable=false,length=100)private String nombres;@NotBlank @Column(nullable=false,length=100)private String apellidos;@Column(length=15)private String telefono;@Email @Column(length=100)private String correo;@ManyToOne(optional=false)@JoinColumn(name="id_especialidad",nullable=false)private Especialidad especialidad;@Column(length=1)private String estado="A";public Long getId(){return id;}public String getCmp(){return cmp;}public void setCmp(String x){cmp=x;}public String getNombres(){return nombres;}public void setNombres(String x){nombres=x;}public String getApellidos(){return apellidos;}public void setApellidos(String x){apellidos=x;}public String getTelefono(){return telefono;}public void setTelefono(String x){telefono=x;}public String getCorreo(){return correo;}public void setCorreo(String x){correo=x;}public Especialidad getEspecialidad(){return especialidad;}public void setEspecialidad(Especialidad x){especialidad=x;}public String getEstado(){return estado;}public void setEstado(String x){estado=x;}}
